window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[266]={"id":"266","numero":266,"titre":"Polykystose rénale","objectifs":[{"id":"266-1","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la prévalence de la polykystose rénale","contenu":"<p>La <span class=\"kw-def\"><strong>polykystose rénale autosomique dominante (PKRAD)</strong></span> est la <span class=\"kw-clinique\">plus fréquente des néphropathies héréditaires</span> — c'est la première <span class=\"kw-def\">maladie rénale monogénique</span> de l'<span class=\"kw-clinique\">adulte</span>. Elle se révèle volontiers chez l'<span class=\"kw-clinique\">adulte jeune</span> et représente une cause notable d'<span class=\"kw-clinique\">insuffisance rénale terminale</span>.</p>\n      <table >\n        <thead><tr><th>Donnée épidémiologique</th><th>Chiffre</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\"><strong>Prévalence</strong></span> (population générale)</td><td><span class=\"kw-chiffre\">≈ 1 / 1000</span></td></tr>\n          <tr><td>Part dans <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">insuffisances rénales terminales</span> (IRT)</td><td><span class=\"kw-chiffre\">8 – 10 %</span> des IRT</td></tr>\n          <tr><td><span class=\"kw-def\">Transmission</span></td><td><span class=\"kw-def\">autosomique dominante</span> <span class=\"kw-def\">(cf. objectif dédié)</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> PKRAD = <span class=\"kw-def\">néphropathie héréditaire la plus fréquente</span> (<span class=\"kw-chiffre\">1/1000</span>), responsable de <span class=\"kw-chiffre\">8-10 %</span> des <span class=\"kw-clinique\">insuffisances rénales terminales</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 264 — <span class=\"kw-ci\">Insuffisance rénale</span> chronique</em></p>","frequence":1},{"id":"266-2","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître le mode de transmission autosomique dominant","contenu":"<p>La PKRAD se transmet sur un mode <span class=\"kw-def\"><strong>autosomique dominant</strong></span> : un parent atteint a un <span class=\"kw-chiffre\">risque de 50 %</span> de transmettre la maladie à chaque enfant. La <span class=\"kw-clinique\">descendance d'un sujet non atteint</span> est indemne.</p>\n      <ul>\n        <li><span class=\"kw-etio\">Mutation de novo</span> (non transmise par un parent) dans <span class=\"kw-chiffre\">≈ 5 %</span> des cas</li>\n        <li>Maladie génétiquement hétérogène :<span class=\"kw-chiffre\"> 2 g</span>ènes impliqués dans la majorité des cas</li>\n      </ul>\n      <p><strong><span class=\"kw-clinique\">Les</span> deux gènes de la PKRAD</strong></p>\n      <table >\n        <thead><tr><th>Gène</th><th>Fréquence</th><th>Protéine mutée</th><th>Âge moyen de l'IRT</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\"><strong>PKD1</strong></span></td><td><span class=\"kw-chiffre\">85 %</span></td><td><span class=\"kw-bio\">polycystine 1</span></td><td><span class=\"kw-chiffre\">≈ 55 ans</span> <span class=\"kw-def\">(forme la plus sévère)</span></td></tr>\n          <tr><td><span class=\"kw-def\"><strong>PKD2</strong></span></td><td><span class=\"kw-chiffre\">15 %</span></td><td><span class=\"kw-bio\">polycystine 2</span></td><td><span class=\"kw-chiffre\">≈ 70 ans</span> <span class=\"kw-def\">(forme plus tardive)</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Transmission <span class=\"kw-def\">autosomique dominante</span> → <span class=\"kw-chiffre\">50 %</span> de risque par enfant ; <span class=\"kw-chiffre\">5 %</span> de <span class=\"kw-etio\">mutations de novo</span>. <span class=\"kw-def\">PKD1</span> (<span class=\"kw-chiffre\">85 %</span>, IRT <span class=\"kw-chiffre\">~55 ans</span>) est plus sévère que <span class=\"kw-def\">PKD2</span> (<span class=\"kw-chiffre\">15 %</span>, IRT <span class=\"kw-chiffre\">~70 ans</span>).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 264 — <span class=\"kw-ci\">Insuffisance rénale</span> chronique</em></p>","frequence":2},{"id":"266-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la présentation clinique et les circonstances du diagnostic de la polykystose rénale","contenu":"<p>Le diagnostic de PKRAD est le plus souvent porté chez l'<span class=\"kw-clinique\"><strong>adulte jeune</strong></span>. La maladie reste longtemps silencieuse : <span class=\"kw-clinique\">2 à 4 décennies</span> sans anomalie rénale clinique perceptible avant l'apparition des premiers symptômes.</p>\n      <p><strong>Mécanisme de l'atteinte rénale</strong> — la PKRAD est une <span class=\"kw-def\">néphropathie tubulo-interstitielle chronique</span> :</p>\n      <ul>\n        <li>développement <span class=\"kw-clinique\">progressif</span> de multiples <span class=\"kw-def\">kystes</span> aux dépens de n'importe quel segment des tubules rénaux</li>\n        <li>chaque kyste = cavité liquidienne bordée d'un épithélium dérivé des <span class=\"kw-bio\">cellules tubulaires</span> ; croissance par <span class=\"kw-clinique\">prolifération</span> cellulaire + <span class=\"kw-clinique\">sécrétion de fluide</span></li>\n        <li>conséquence : <span class=\"kw-clinique\">compression</span> et <span class=\"kw-clinique\">fibrose progressive</span> du parenchyme rénal non kystique</li>\n      </ul>\n      <p><strong>Traduction clinique et circonstances de découverte</strong></p>\n      <table >\n        <thead><tr><th>Circonstance</th><th>Éléments</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>Signes rénaux</strong></span></td><td><span class=\"kw-clinique\">gros reins bilatéraux</span> ; <span class=\"kw-clinique\">pesanteurs lombaires et abdominales</span> particulièrement invalidantes</td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>HTA</strong></span></td><td>très fréquente, <span class=\"kw-clinique\">précoce</span> : apparaît <span class=\"kw-chiffre\">avant 40 ans</span> (parfois dès l'<span class=\"kw-clinique\">enfance</span>), <strong>avant</strong> le déclin de la fonction rénale</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Manifestations révélatrices</strong></span></td><td><span class=\"kw-clinique\">douleurs lombaires</span> ; <span class=\"kw-clinique\">hématurie macroscopique</span> ; complication aiguë (infection, hémorragie ou migration lithiasique intrakystique)</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Dépistage / fortuit</strong></span></td><td><span class=\"kw-clinique\">histoire familiale</span> connue ; découverte fortuite à l'<span class=\"kw-imagerie\">échographie</span> ou au <span class=\"kw-imagerie\">scanner</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Atteintes extra-rénales</strong> — la PKRAD est une maladie systémique :</p>\n      <ul>\n        <li><span class=\"kw-etio\">Kystes hépatiques</span> (atteinte extra-rénale la plus fréquente)</li>\n        <li><span class=\"kw-alerte\">Anévrismes des artères cérébrales</span></li>\n        <li><span class=\"kw-etio\">Hernie inguinale</span> · <span class=\"kw-etio\">diverticulose colique</span> · <span class=\"kw-etio\">prolapsus de la valve mitrale</span></li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Découverte chez l'<span class=\"kw-clinique\">adulte jeune</span> après une longue phase muette. Trois portes d'entrée classiques : <span class=\"kw-alerte\">HTA précoce</span>, <span class=\"kw-clinique\">douleurs lombaires / gros reins</span>, <span class=\"kw-clinique\">hématurie macroscopique</span> — ou <span class=\"kw-def\">dépistage</span> familial. Toujours penser <span class=\"kw-def\">maladie systémique</span> (foie, anévrismes cérébraux).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 264 — <span class=\"kw-ci\">Insuffisance rénale</span> chronique · 224 — <span class=\"kw-etio\">HTA</span> · 260 — <span class=\"kw-bio\">Hématurie</span></em></p>","frequence":3},{"id":"266-4","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les critères diagnostiques de la polykystose rénale","contenu":"<p>Le diagnostic de PKRAD repose sur deux piliers : l'<span class=\"kw-clinique\">histoire familiale</span> et l'<span class=\"kw-imagerie\">imagerie rénale</span>. L'<span class=\"kw-bio\">analyse génétique</span> n'est demandée que dans des cas particuliers.</p>\n      <table >\n        <thead><tr><th>Critère</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>Histoire familiale</strong></span></td><td><span class=\"kw-clinique\">IRC sur néphropathie kystique</span> chez un apparenté du propositus ; <strong>arbre généalogique complet</strong> indispensable dans tous <span class=\"kw-clinique\">les</span> cas</td></tr>\n          <tr><td><span class=\"kw-imagerie\"><strong>Imagerie</strong></span></td><td><span class=\"kw-imagerie\">échographie abdominale</span> (ou <span class=\"kw-imagerie\">TDM / IRM</span>, sensibilité supérieure) : <span class=\"kw-radio\">gros reins bilatéraux</span> (<span class=\"kw-chiffre\">&gt; 12 cm</span>), contours déformés par des <span class=\"kw-radio\">kystes multiples bilatéraux</span> ; <span class=\"kw-etio\">polykystose hépatique</span> chez <span class=\"kw-chiffre\">30-70 %</span></td></tr>\n          <tr><td><span class=\"kw-bio\"><strong>Génétique</strong></span></td><td>pas d'indication en routine ❌ ; réservée au <span class=\"kw-alerte\">doute diagnostique sans histoire familiale</span> ou à une <span class=\"kw-alerte\">présentation atypique</span> à l'imagerie (autre néphropathie kystique possible)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Valeur diagnostique de l'imagerie selon l'âge</strong> — le nombre et la taille des kystes augmentent avec l'âge :</p>\n      <table >\n        <thead><tr><th>Âge</th><th>Apport de l'absence de kyste</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\">&lt; 40 ans</span></td><td>l'<span class=\"kw-clinique\">absence de kyste n'exclut pas</span> la maladie</td></tr>\n          <tr><td><span class=\"kw-chiffre\">30 – 39 ans</span></td><td>l'absence de kyste <span class=\"kw-alerte\">exclut la maladie à 99 %</span></td></tr>\n          <tr><td><span class=\"kw-chiffre\">&gt; 40 ans</span></td><td>la présence de <span class=\"kw-chiffre\">0 – 1 kyste</span> exclut la maladie</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Critères échographiques chez <span class=\"kw-clinique\">les</span> apparentés d'un sujet atteint</strong> <span class=\"kw-def\">(ancien référentiel)</span></p>\n      <table >\n        <thead><tr><th>Âge</th><th><span class=\"kw-def\">Critère diagnostique</span></th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\">15 – 39 ans</span></td><td><span class=\"kw-chiffre\">≥ 3 kystes rénaux</span> (uni ou bilatéraux)</td></tr>\n          <tr><td><span class=\"kw-chiffre\">40 – 59 ans</span></td><td><span class=\"kw-chiffre\">≥ 2 kystes</span> dans chaque rein</td></tr>\n          <tr><td><span class=\"kw-chiffre\">&gt; 60 ans</span></td><td><span class=\"kw-chiffre\">&gt; 4 kystes</span> dans chaque rein</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Diagnostic = <span class=\"kw-clinique\">histoire familiale</span> + <span class=\"kw-imagerie\">échographie</span> (gros reins &gt;<span class=\"kw-chiffre\"> 12 cm</span>, kystes multiples bilatéraux). Avant <span class=\"kw-chiffre\">40 ans</span>, une <span class=\"kw-imagerie\">échographie</span> normale <strong>n'élimine pas</strong> la maladie. <span class=\"kw-etio\">Génétique</span> <span class=\"kw-alerte\">non systématique</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 264 — <span class=\"kw-ci\">Insuffisance rénale</span> chronique</em></p>","frequence":1},{"id":"266-5","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les principales complications de la polykystose rénale","contenu":"<p><span class=\"kw-clinique\">Les</span> complications de la PKRAD sont à la fois rénales et extra-rénales. L'<span class=\"kw-ci\">insuffisance rénale</span> chronique est la complication sévère <strong>la plus fréquente</strong>.</p>\n      <p><strong>1 · Complications rénales</strong></p>\n      <table >\n        <thead><tr><th>Complication</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\"><strong>Insuffisance rénale chronique</strong></span></td><td>complication sévère <strong>la plus fréquente</strong> ; IR <span class=\"kw-clinique\">progressive</span>, <span class=\"kw-alerte\">sans protéinurie ni hématurie</span> ❌ ; déclin du <span class=\"kw-bio\">DFG</span> de <span class=\"kw-chiffre\">2 à 5 mL/min/an</span> une fois l'IR installée ; <span class=\"kw-clinique\">IRT</span> habituelle entre <span class=\"kw-chiffre\">50 et 70 ans</span></td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>Infection du rein</strong></span></td><td><span class=\"kw-etio\">PNA</span> ou <span class=\"kw-etio\">infection intrakystique</span> : toute <span class=\"kw-clinique\">fièvre</span> justifie un <span class=\"kw-bio\">ECBU</span> et doit la faire évoquer</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Douleurs lombaires sans fièvre</strong></span></td><td><span class=\"kw-etio\">hémorragie intrakystique</span> (distension brutale d'un kyste) ; <span class=\"kw-etio\">migration lithiasique</span> (<span class=\"kw-imagerie\">TDM</span> utile : acide urique <span class=\"kw-chiffre\">≈ 500 UH</span>, oxalate de calcium <span class=\"kw-chiffre\">1000-1500 UH</span>)</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Hématurie macroscopique</strong></span></td><td>+ douleurs lombaires sans <span class=\"kw-clinique\">fièvre</span> : le plus souvent <span class=\"kw-etio\">hémorragie intrakystique</span> rompue dans la voie excrétrice ; plus rarement <span class=\"kw-etio\">migration lithiasique</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Facteurs du <span class=\"kw-def\">pronostic</span> rénal</strong></p>\n      <ul>\n        <li>Gène muté : <span class=\"kw-def\">PKD1</span> → IRT plus précoce que <span class=\"kw-def\">PKD2</span></li>\n        <li>Type de mutation (caractère tronquant ou non)</li>\n        <li><span class=\"kw-imagerie\">Volume rénal total</span> (mesuré en <span class=\"kw-imagerie\">TDM</span>/<span class=\"kw-imagerie\">IRM</span>) : prédit le risque d'apparition et la vitesse de progression de l'IR <span class=\"kw-def\">(normal ≈ 300 mL, jusqu'à <span class=\"kw-chiffre\">6-7 L</span> dans les formes marquées)</span></li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Infection intrakystique</strong> = équivalent d'un <span class=\"kw-alerte\">abcès rénal</span> : <span class=\"kw-clinique\">fièvre</span> ± <span class=\"kw-clinique\">frissons</span>, douleurs lombaires, signes urinaires rares ; <span class=\"kw-bio\">syndrome inflammatoire</span> (hyperPNN, <span class=\"kw-bio\">CRP</span> élevée) ; <span class=\"kw-bio\">ECBU</span> avec <span class=\"kw-bio\">bactériurie inconstante</span> (urines souvent stériles) ; <span class=\"kw-imagerie\">TDM</span> (± <span class=\"kw-imagerie\">TEP-TDM</span>). Traitement : <span class=\"kw-ttt\">biantibiothérapie</span> à bonne diffusion intrakystique (<span class=\"kw-ttt\">FQ + triméthoprime-sulfaméthoxazole</span>) ; <span class=\"kw-clinique\">ponction du kyste</span> si <span class=\"kw-clinique\">fièvre</span>/douleurs persistant &gt;<span class=\"kw-chiffre\"> 1 semaine</span> sous ATB.</div>\n      <p><strong>2 · Complications extra-rénales</strong></p>\n      <table >\n        <thead><tr><th>Atteinte</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\"><strong>Kystes hépatiques</strong></span></td><td>très fréquents (<span class=\"kw-chiffre\">30-70 %</span>), quel que soit le gène ; plus tardifs que <span class=\"kw-clinique\">les</span> kystes rénaux, plus précoces chez la femme ; le plus souvent asymptomatiques ; <span class=\"kw-alerte\">jamais d'insuffisance hépatique</span> ⚠️ même en cas de polykystose hépatique massive</td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>Anévrisme intracrânien</strong></span></td><td><span class=\"kw-def\">prévalence</span> <span class=\"kw-chiffre\">8-13 %</span> (<span class=\"kw-bio\">vs</span> <span class=\"kw-chiffre\">3 %</span> en population générale ; <span class=\"kw-chiffre\">18-22 %</span> si ATCD familial d'anévrisme) ; circulation antérieure, polygone de Willis ; âge moyen de <span class=\"kw-alerte\">rupture</span> <span class=\"kw-chiffre\">≈ 41 ans</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-def\">Dépistage</span> de l'anévrisme intracrânien.</strong> Indiqué chez <span class=\"kw-clinique\">les</span> patients de <span class=\"kw-chiffre\">&lt; 50 ans</span> avec : apparenté du 1er degré ayant un <span class=\"kw-alerte\">ATCD d'anévrisme cérébral</span> (rompu ou non), ou <span class=\"kw-clinique\">profession à risque</span> (ex. pilote de ligne). Modalité : <span class=\"kw-imagerie\">IRM cérébrale non injectée, séquences 3D-TOF</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 264 — <span class=\"kw-ci\">Insuffisance rénale</span> chronique · 161 — <span class=\"kw-clinique\">Infection urinaire</span> · 265 — Lithiase urinaire · 340 — <span class=\"kw-alerte\">AVC</span></em></p>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/circle-of-willis","label":"Radiopaedia : Circle of Willis (anévrismes)"}]},{"id":"266-6","rang":"A","rubrique":"Prise en charge","titre":"Connaître le traitement non spécifique de la polykystose rénale","contenu":"<p>La prise en charge non spécifique de la PKRAD repose sur la <span class=\"kw-clinique\">néphroprotection</span> (mesures communes à toute maladie rénale chronique), des <span class=\"kw-ttt\">boissons abondantes</span> et une <span class=\"kw-clinique\">surveillance régulière</span>.</p>\n      <table >\n        <thead><tr><th>Volet</th><th>Mesures</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>Surveillance</strong></span></td><td><span class=\"kw-clinique\">pression artérielle</span> + <span class=\"kw-bio\">créatininémie</span> au moins <span class=\"kw-chiffre\">1×/an</span></td></tr>\n          <tr><td><span class=\"kw-ttt\"><strong>Boissons</strong></span></td><td><span class=\"kw-ttt\">apports hydriques abondants</span> (<span class=\"kw-chiffre\">≈ 2 L/jour</span>) pour prévenir <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">lithiases</span> et les <span class=\"kw-clinique\">infections</span></td></tr>\n          <tr><td><span class=\"kw-ttt\"><strong>Néphroprotection</strong></span></td><td>mesures non spécifiques d'une <span class=\"kw-def\">MRC</span> (contrôle tensionnel, <span class=\"kw-ttt\">IEC/ARA2</span>, restriction sodée…) — <strong>seule particularité de la PKRAD :</strong> <span class=\"kw-ci\">absence d'indication des inhibiteurs du SGLT2</span></td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Traitement spécifique</strong></span> <span class=\"kw-def\">(hors programme)</span></td><td><span class=\"kw-ttt\">tolvaptan</span> ; <span class=\"kw-ttt\">analogues de la somatostatine</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Au <span class=\"kw-def\">stade</span> d'<span class=\"kw-ci\">insuffisance rénale</span> terminale</strong></p>\n      <ul>\n        <li><span class=\"kw-ttt\">Hémodialyse</span> ou <span class=\"kw-ttt\">dialyse péritonéale</span></li>\n        <li><span class=\"kw-ttt\"><strong>Transplantation rénale</strong></span> = <span class=\"kw-alerte\">traitement de choix</span> ; <span class=\"kw-clinique\">néphrectomie</span> préalable d'un rein polykystique parfois nécessaire (rein volumineux atteignant la région iliaque, gênant l'implantation du greffon)</li>\n      </ul>\n      <p><strong>Conseil <span class=\"kw-etio\">génétique</span> et <span class=\"kw-def\">dépistage</span> des apparentés</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Conseil génétique</span> : risque de transmission à un enfant = <span class=\"kw-chiffre\">50 %</span> ; descendance d'un sujet non atteint = indemne</li>\n        <li><span class=\"kw-clinique\">Adulte &gt; 18 ans</span> : <span class=\"kw-imagerie\">échographie</span> de <span class=\"kw-def\">dépistage</span> proposée (après information sur <span class=\"kw-clinique\">les</span> résultats possibles)</li>\n        <li><span class=\"kw-clinique\">Enfant &lt; 18 ans</span> : <span class=\"kw-bio\">PA</span> au moins <span class=\"kw-chiffre\">1×/an</span> ; intérêt de l'<span class=\"kw-imagerie\">échographie débattu</span> en l'absence de symptômes (aucun traitement disponible à cet âge)</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Néphroprotection standard de MRC <strong>sauf</strong> <span class=\"kw-clinique\">les</span> <span class=\"kw-ci\">iSGLT2 (non indiqués)</span> ; <span class=\"kw-ttt\">2 L d'eau/jour</span> ; <span class=\"kw-def\">surveillance</span> <span class=\"kw-clinique\">PA + créatinine</span> annuelle. Au <span class=\"kw-def\">stade</span> terminal, la <span class=\"kw-alerte\">transplantation rénale</span> est le traitement de choix.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 264 — <span class=\"kw-ci\">Insuffisance rénale</span> chronique · 201 — Transplantation d'organe · 224 — <span class=\"kw-etio\">HTA</span></em></p>","frequence":2}],"astuces":[],"strategie":{"urgence":"<p><strong>Infection rénale <span class=\"q\">— PNA ou infection intrakystique</span></strong></p><p><span class=\"kw-ttt\">Ponction du kyste infecté</span> si <span class=\"kw-alerte\">fièvre + douleurs persistant &gt; 1 semaine</span> sous <span class=\"kw-ttt\">antibiothérapie</span></p><ul><li>Toute <span class=\"kw-alerte\">fièvre</span> d'origine incertaine → <span class=\"kw-bio\">ECBU</span> et évoquer l'infection</li><li><span class=\"kw-def\">Infection intrakystique</span> = équivalent d'un <span class=\"kw-alerte\">abcès rénal</span> : <span class=\"kw-bio\">bactériurie inconstante</span> (urines souvent stériles), <span class=\"kw-imagerie\">TDM</span> &plusmn; <span class=\"kw-imagerie\">TEP-TDM</span></li><li><span class=\"kw-ttt\">Biantibiothérapie</span> à bonne diffusion intrakystique : <span class=\"kw-ttt\">fluoroquinolone + triméthoprime-sulfaméthoxazole</span></li><li><span class=\"kw-ttt\">PNA</span> : <span class=\"kw-ttt\">FQ</span> ou <span class=\"kw-ttt\">TMP-SMX</span> pendant <span class=\"kw-chiffre\">3 à 4 semaines</span></li></ul><p><strong>Hémorragie intrakystique</strong></p><p><span class=\"kw-imagerie\">TDM</span> utile au diagnostic</p><ul><li><span class=\"kw-clinique\">Douleurs lombaires</span> <span class=\"kw-alerte\">sans fièvre</span> (distension brutale d'un kyste)</li><li><span class=\"kw-clinique\">Hématurie macroscopique</span> si <span class=\"kw-alerte\">rupture</span> dans la voie excrétrice (cause la plus fréquente)</li></ul><p><strong>Migration lithiasique</strong></p><ul><li><span class=\"kw-clinique\">Douleurs lombaires</span> <span class=\"kw-alerte\">sans fièvre</span>, plus rarement <span class=\"kw-clinique\">hématurie</span></li><li><span class=\"kw-imagerie\">TDM</span> : <span class=\"kw-etio\">acide urique</span> <span class=\"kw-chiffre\">&approx; 500 UH</span> &middot; <span class=\"kw-etio\">oxalate de calcium</span> <span class=\"kw-chiffre\">1000-1500 UH</span></li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">Fièvre</span> au cours d'une PKRAD → toujours évoquer une <span class=\"kw-etio\">infection rénale</span> (<span class=\"kw-bio\">ECBU</span> systématique)</li><li><span class=\"kw-alerte\">Hématurie macroscopique</span> + <span class=\"kw-clinique\">douleurs lombaires</span> sans <span class=\"kw-clinique\">fièvre</span> → <span class=\"kw-etio\">hémorragie intrakystique</span></li><li><span class=\"kw-alerte\">Fièvre + douleurs lombaires persistant &gt; 1 semaine</span> sous antibiotiques → kyste infecté à <span class=\"kw-ttt\">ponctionner</span></li><li><span class=\"kw-alerte\">Anévrisme intracrânien</span> : <span class=\"kw-def\">prévalence</span> <span class=\"kw-chiffre\">8-13 %</span> (<span class=\"kw-chiffre\">18-22 %</span> si ATCD familial), âge moyen de <span class=\"kw-alerte\">rupture</span> <span class=\"kw-chiffre\">&approx; 41 ans</span></li><li><span class=\"kw-alerte\">HTA précoce</span> (<span class=\"kw-chiffre\">&lt; 40 ans</span>, parfois dès l'enfance), avant le déclin de la fonction rénale</li></ul>","principes":"<p>Prise en charge non spécifique = <span class=\"kw-clinique\">néphroprotection</span> d'une <span class=\"kw-def\">maladie rénale chronique</span> + <span class=\"kw-ttt\">boissons abondantes</span> + <span class=\"kw-def\">surveillance</span>. <strong>Seule particularité de la PKRAD :</strong> <span class=\"kw-ci\">absence d'indication des inhibiteurs du SGLT2</span>.</p><p><strong>Mesures de fond</strong></p><p>Traitement spécifique <em>(hors programme)</em> : <span class=\"kw-ttt\">tolvaptan</span>, <span class=\"kw-ttt\">analogues de la somatostatine</span></p><ul><li><span class=\"kw-ttt\">Boissons abondantes</span> (<span class=\"kw-chiffre\">&approx; 2 L/jour</span>) pour prévenir <span class=\"kw-clinique\">lithiases</span> et <span class=\"kw-clinique\">infections</span></li><li><span class=\"kw-ttt\">Néphroprotection</span> standard de <span class=\"kw-def\">MRC</span> : contrôle tensionnel, <span class=\"kw-ttt\">IEC/ARA2</span>, restriction sodée</li><li><span class=\"kw-ci\">Pas d'inhibiteurs du SGLT2</span> (non indiqués dans la PKRAD)</li></ul><p><strong><span class=\"kw-def\">Stade</span> d'<span class=\"kw-ci\">insuffisance rénale</span> terminale</strong></p><ul><li><span class=\"kw-ttt\">Hémodialyse</span> ou <span class=\"kw-ttt\">dialyse péritonéale</span></li><li><span class=\"kw-ttt\">Transplantation rénale</span> = <span class=\"kw-alerte\">traitement de choix</span></li><li><span class=\"kw-ttt\">Néphrectomie</span> préalable parfois nécessaire (rein volumineux atteignant la région iliaque, gênant l'implantation du greffon)</li></ul>","suivi":"<p><strong><span class=\"kw-def\">Surveillance</span> de la fonction rénale</strong></p><ul><li><span class=\"kw-clinique\">Pression artérielle</span> + <span class=\"kw-bio\">créatininémie</span> au moins <span class=\"kw-chiffre\">1&times;/an</span></li><li>IR <span class=\"kw-clinique\">progressive</span> : déclin du <span class=\"kw-bio\">DFG</span> de <span class=\"kw-chiffre\">2 à 5 mL/min/an</span> une fois installée</li></ul><p><strong>Conseil <span class=\"kw-etio\">génétique</span></strong></p><ul><li>Risque de transmission à chaque enfant = <span class=\"kw-chiffre\">50 %</span></li><li>Descendance d'un sujet <span class=\"kw-clinique\">non atteint</span> = indemne</li></ul><p><strong><span class=\"kw-def\">Dépistage</span> des apparentés</strong></p><ul><li><span class=\"kw-clinique\">Adulte &gt; 18 ans</span> : <span class=\"kw-imagerie\">échographie</span> proposée (après information sur <span class=\"kw-clinique\">les</span> résultats possibles)</li><li><span class=\"kw-clinique\">Enfant &lt; 18 ans</span> : <span class=\"kw-bio\">PA</span> au moins <span class=\"kw-chiffre\">1&times;/an</span> ; intérêt de l'<span class=\"kw-imagerie\">échographie</span> débattu (aucun traitement disponible à cet âge)</li></ul><p><strong><span class=\"kw-def\">Dépistage</span> de l'anévrisme intracrânien</strong></p><p>Si négatif, contrôle <span class=\"kw-imagerie\">imagerie</span> tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">5 ans</span> <em>(ancien référentiel)</em></p><ul><li>Indiqué chez <span class=\"kw-clinique\">les</span> patients de <span class=\"kw-chiffre\">&lt; 50 ans</span> avec apparenté du 1er degré ayant un <span class=\"kw-alerte\">ATCD d'anévrisme cérébral</span> (rompu ou non), ou <span class=\"kw-clinique\">profession à risque</span> (ex. pilote de ligne)</li><li>Modalité : <span class=\"kw-imagerie\">IRM cérébrale non injectée, séquences 3D-TOF</span></li></ul>"},"liensGlobaux":[{"href":"https://manuel4.cuen.fr/spip.php?rubrique20","label":"Collège CUEN — Polykystose rénale"},{"href":"https://radiopaedia.org/articles/autosomal-dominant-polycystic-kidney-disease-1","label":"Radiopaedia : Autosomal Dominant Polycystic Kidney Disease"}],"cards":[{"i":"25c544b6a6d8","n":266,"o":"266-3","u":"Diagnostic positif","t":"Connaître la présentation clinique et les circonstances du diagnostic de la polykystose rénale","q":"Quelles sont les trois portes d'entrée cliniques classiques de la Polykystose Rénale Autosomique Dominante (PKRAD) ?","a":"<ul><li>Une <strong>HTA précoce</strong> (avant 40 ans, parfois dès l'enfance), survenant avant même le déclin de la fonction rénale.</li><li>Des <strong>douleurs lombaires</strong> ou la perception de <strong>gros reins bilatéraux</strong>.</li><li>Une <strong>hématurie macroscopique</strong>.</li></ul>"},{"i":"8d0dfe1fada7","n":266,"o":"266-3","u":"Diagnostic positif","t":"Connaître la présentation clinique et les circonstances du diagnostic de la polykystose rénale","q":"Comment se manifeste classiquement la Polykystose Rénale Autosomique Dominante (PKRAD) sur le plan clinique et à quel âge est-elle le plus souvent diagnostiquée ?","a":"<p>La PKRAD est le plus souvent diagnostiquée chez l'<strong>adulte jeune</strong>, après une longue phase muette de <strong>2 à 4 décennies</strong> sans anomalie rénale clinique perceptible.</p>"},{"i":"be34f58357ce","n":266,"o":"266-3","u":"Diagnostic positif","t":"Connaître la présentation clinique et les circonstances du diagnostic de la polykystose rénale","q":"Quels sont les principaux signes rénaux et extra-rénaux que l'on peut rencontrer dans le cadre de la Polykystose Rénale Autosomique Dominante (PKRAD) ?","a":"<ul><li><strong>Signes rénaux</strong> : <ul><li>Gros reins bilatéraux avec pesanteurs lombaires et abdominales.</li><li>HTA très fréquente et précoce.</li><li>Manifestations révélatrices possibles : douleurs lombaires, hématurie macroscopique, complication aiguë (infection, hémorragie ou migration lithiasique intrakystique).</li></ul></li><li><strong>Atteintes extra-rénales</strong> (la PKRAD est une maladie systémique) : <ul><li><strong>Kystes hépatiques</strong> (atteinte extra-rénale la plus fréquente).</li><li>Anévrismes des artères cérébrales.</li><li>Hernie inguinale.</li><li>Diverticulose colique.</li><li>Prolapsus de la valve mitrale.</li></ul></li></ul>"},{"i":"fdac95cb11b7","n":266,"o":"266-3","u":"Diagnostic positif","t":"Connaître la présentation clinique et les circonstances du diagnostic de la polykystose rénale","q":"Dans quelles circonstances la Polykystose Rénale Autosomique Dominante (PKRAD) peut-elle être dépistée ou découverte fortuitement ?","a":"<p>La PKRAD peut être dépistée lors d'un <strong>dépistage familial</strong> en cas d'histoire familiale connue, ou découverte de manière fortuite lors d'une <strong>échographie</strong> ou d'un <strong>scanner</strong> effectué pour une autre raison.</p>"},{"i":"38757092e53c","n":266,"o":"266-6","u":"Prise en charge","t":"Connaître le traitement non spécifique de la polykystose rénale","q":"Y a-t-il une particularité concernant les inhibiteurs du SGLT2 dans la néphroprotection de la polykystose rénale autosomique dominante (PKRAD) ?","a":"<p>Oui, les <strong>inhibiteurs du SGLT2</strong> n'ont <strong>pas d'indication</strong> dans la néphroprotection de la polykystose rénale autosomique dominante (PKRAD), contrairement à d'autres maladies rénales chroniques.</p>"},{"i":"587b6771014d","n":266,"o":"266-6","u":"Prise en charge","t":"Connaître le traitement non spécifique de la polykystose rénale","q":"Quelle est la principale mesure non spécifique de néphroprotection recommandée dans la polykystose rénale autosomique dominante (PKRAD) ?","a":"<p>La principale mesure est la <strong>néphroprotection</strong>, commune à toute <strong>maladie rénale chronique</strong>, incluant le contrôle tensionnel, les <strong>IEC/ARA2</strong> et la restriction sodée.</p>"},{"i":"624cfc033c6f","n":266,"o":"266-6","u":"Prise en charge","t":"Connaître le traitement non spécifique de la polykystose rénale","q":"Outre la néphroprotection, quelles sont les autres mesures non spécifiques essentielles dans la prise en charge de la polykystose rénale autosomique dominante (PKRAD) ?","a":"<ul><li>Des <strong>apports hydriques abondants</strong> (environ <strong>2 Litres/jour</strong>) pour prévenir les lithiases et les infections urinaires.</li><li>Une <strong>surveillance régulière</strong> de la pression artérielle et de la créatininémie, au moins <strong>1 fois/an</strong>.</li></ul>"}]};